
        <div style="display:flex;gap:8px;overflow-x:auto"><?php foreach($dispTabs ?? [] as $__k => $t): ?><a href="{{ $t['href'] ?? '' }}" style="flex:none;height:40px;padding:0 16px;border-radius:999px;border:1.5px solid #111827;background:{{ $t['bg'] ?? '' }};color:{{ $t['fg'] ?? '' }};font-weight:700;font-size:13px;display:flex;align-items:center">{{ $t['label'] ?? '' }}</a><?php endforeach; ?></div>
        <div style="background:#FFFFFF;border:1px solid #E5E7EB;border-radius:18px;overflow:hidden"><?php foreach($disputes ?? [] as $__k => $d): ?><div style="padding:16px 18px;border-bottom:1px solid #F3F4F6;display:flex;flex-direction:column;gap:10px"><div style="display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap"><span style="display:flex;flex-direction:column;gap:2px"><b style="font-size:15px">{{ $d['reason'] ?? '' }} · {{ $d['amount'] ?? '' }}</b><span style="font-size:12px;color:#4B5563">{{ $d['no'] ?? '' }} · Buyer {{ $d['buyer'] ?? '' }} · Seller {{ $d['seller'] ?? '' }} · opened {{ $d['date'] ?? '' }}</span></span><span style="height:26px;padding:0 10px;border-radius:999px;background:{{ $d['bg'] ?? '' }};color:{{ $d['fg'] ?? '' }};font-size:12px;font-weight:800;display:flex;align-items:center">{{ $d['status'] ?? '' }}</span></div><span style="font-size:14px;color:#374151;line-height:1.5">{{ $d['summary'] ?? '' }}</span><?php if(!empty($d['open'])): ?><div style="display:flex;gap:8px;flex-wrap:wrap"><button data-post="{{ $d['postUrl'] ?? '' }}" data-field-action="refund" data-confirm="Refund the buyer in full?" style="height:40px;padding:0 16px;border-radius:999px;border:0;background:#C2410C;color:#FFFFFF;font-weight:700;font-size:13px;cursor:pointer">Refund buyer in full</button><?php if(!empty($d['canManual'])): ?><button data-post="{{ $d['postUrl'] ?? '' }}" data-field-action="refund_manual" data-confirm="Only press this after you refunded the buyer in PayPal. Continue?" style="height:40px;padding:0 16px;border-radius:999px;border:1.5px solid #C2410C;background:#FFFFFF;color:#C2410C;font-weight:700;font-size:13px;cursor:pointer">I refunded in PayPal</button><?php endif; ?><button data-post="{{ $d['postUrl'] ?? '' }}" data-field-action="seller" data-ask="Note for the buyer (why the seller is right)" style="height:40px;padding:0 16px;border-radius:999px;border:1.5px solid #111827;background:#FFFFFF;font-weight:700;font-size:13px;cursor:pointer">Side with seller</button></div><?php endif; ?></div><?php endforeach; ?></div>
      